// spec: .qa/e2e/specs/navigation.md (4.1)
// seed: tests/seed.user.spec.ts
// ПРЕДОХРАНИТЕЛЬ: запрос выхода перехватывается (204) — иначе он отзовёт общую сессию user.json.
// Сессия меняется только в окне теста (localStorage), файл user.json не перезаписывается.
import { test, expect } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

test.describe('Навигация — выход из аккаунта', () => {
  test('Выход с подтверждением = Figma 12.6: «ביטול» оставляет в аккаунте, «יציאה» → /welcome, назад/reload не возвращают #fb3b8d53 @iphone @data', async ({ page }) => {
    // 1. Предохранитель до любых действий (только веб — перехват запроса)
    let logoutCalls = 0;
    await page.route('**/auth/v1/logout**', async (r) => {
      logoutCalls++;
      await r.fulfill({ status: 204 });
    });

    // 2. /home → таб «חשבון» (есть куда вернуться «назад») → «יציאה מהחשבון»
    await page.goto('/home');
    await page.getByRole('tab', { name: 'חשבון' }).filter({ visible: true }).click();
    await expect(page).toHaveURL(/\/account$/);
    const exit = page.getByRole('button', { name: 'יציאה מהחשבון' }).filter({ visible: true });
    await exit.click();

    // 3. Окно 12.6
    const dialog = page.getByRole('dialog').filter({ visible: true });
    await expect(dialog.getByRole('heading', { name: 'לצאת מהחשבון?' })).toBeVisible();
    await expect(dialog.getByText('אפשר להתחבר שוב בכל רגע.')).toBeVisible();
    await expect(dialog.getByText(/ניטור לא יפעל בטלפון הזה/).first()).toBeVisible();
    await expect(dialog.getByText(/לא יגיעו אליו התרעות/).first()).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'יציאה', exact: true })).toBeVisible();
    await expect(dialog.getByRole('button', { name: 'ביטול', exact: true })).toBeVisible();

    // «ביטול» → окно закрыто, остаёмся в «חשבון»
    await dialog.getByRole('button', { name: 'ביטול', exact: true }).click();
    await expect(page.getByRole('dialog').filter({ visible: true })).toHaveCount(0);
    await expect(page).toHaveURL(/\/account$/);
    await expect(page.getByRole('tab', { name: 'חשבון' }).filter({ visible: true })).toHaveAttribute('aria-selected', 'true');
    expect(logoutCalls).toBe(0);

    // 4. Снова «יציאה מהחשבון» → «יציאה»
    await exit.click();
    await page.getByRole('dialog').filter({ visible: true }).getByRole('button', { name: 'יציאה', exact: true }).click();
    await expect(page).toHaveURL(/\/welcome/);
    const tokenGone = await page.evaluate(() => !Object.keys(localStorage).some((k) => /^sb-.*-auth-token$/.test(k)));
    expect(logoutCalls >= 1 || tokenGone, 'запрос выхода был или токен удалён').toBe(true);

    // 5. «Назад» и reload не возвращают в аккаунт (только веб: история браузера)
    await page.goBack();
    await expect(page).toHaveURL(/\/(welcome|sign-in)/);
    await expect(page.getByRole('button', { name: 'יציאה מהחשבון' }).filter({ visible: true })).toHaveCount(0);
    await page.reload();
    await expect(page).toHaveURL(/\/(welcome|sign-in)/);
    await expect(page.getByRole('button', { name: 'יציאה מהחשבון' }).filter({ visible: true })).toHaveCount(0);
  });
});
